import * as THREE from 'three';

// Fuentes necesarias en <head>:
// <link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;1,300;1,400&family=Allura&display=swap" rel="stylesheet">

const W = 1024, H = 716;

// ── Voltear canvas horizontalmente para corregir UV ──────────
function flipCanvas(src) {
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const ctx = c.getContext('2d');
  ctx.translate(W, 0);
  ctx.scale(-1, 1);
  ctx.drawImage(src, 0, 0);
  return c;
}

// ── Utilidades ──────────────────────────────────────────────

function fondoGrano(ctx, kraft = false) {
  const grad = ctx.createLinearGradient(0, 0, W, H);
  if (kraft) {
    grad.addColorStop(0, '#F5EDD8'); grad.addColorStop(0.5, '#EDE0C4'); grad.addColorStop(1, '#E5D8B8');
  } else {
    grad.addColorStop(0, '#FDFBF7'); grad.addColorStop(0.5, '#F9F6EF'); grad.addColorStop(1, '#F4F0E6');
  }
  ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H);
  for (let i = 0; i < 25000; i++) {
    ctx.beginPath(); ctx.arc(Math.random()*W, Math.random()*H, Math.random()*1.1, 0, Math.PI*2);
    ctx.fillStyle = `rgba(0,0,0,${Math.random()*0.06+0.01})`; ctx.fill();
  }
  for (let i = 0; i < H; i += 3) {
    ctx.strokeStyle = `rgba(0,0,0,${Math.random()*0.03+0.01})`; ctx.lineWidth = 0.4;
    ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(W, i); ctx.stroke();
  }
}

function marcoDorado(ctx) {
  ctx.strokeStyle = 'rgba(212,160,23,0.75)'; ctx.lineWidth = 2.5;
  ctx.strokeRect(40, 40, W-80, H-80);
  ctx.strokeStyle = 'rgba(212,160,23,0.35)'; ctx.lineWidth = 1;
  ctx.strokeRect(54, 54, W-108, H-108);
  [[40,40],[W-40,40],[40,H-40],[W-40,H-40]].forEach(([x,y]) => {
    ctx.beginPath(); ctx.arc(x, y, 3.5, 0, Math.PI*2);
    ctx.fillStyle = 'rgba(212,160,23,0.85)'; ctx.fill();
  });
}

function rama(ctx) {
  ctx.save(); ctx.translate(68, 68); ctx.scale(1.7, 1.7);
  ctx.strokeStyle = 'rgba(180,150,80,0.55)'; ctx.lineWidth = 0.8; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(0, 40); ctx.bezierCurveTo(5, 25, 15, 10, 25, 0); ctx.stroke();
  [{t:0.25,a:-0.5,s:7},{t:0.50,a:0.6,s:8},{t:0.72,a:-0.4,s:6},{t:0.88,a:0.5,s:5}].forEach(({t,a,s}) => {
    const x = 3*(1-t)*(1-t)*t*5 + 3*(1-t)*t*t*15 + t*t*t*25;
    const y = 3*(1-t)*(1-t)*t*25 + 3*(1-t)*t*t*10 + t*t*t*0 + (1-t)*(1-t)*(1-t)*40;
    ctx.save(); ctx.translate(x, y); ctx.rotate(a);
    ctx.beginPath(); ctx.moveTo(0,0);
    ctx.bezierCurveTo(s*0.5,-s*0.4,s,-s*0.1,s*0.8,s*0.3);
    ctx.bezierCurveTo(s*0.5,s*0.5,0,s*0.1,0,0);
    ctx.fillStyle = 'rgba(160,135,70,0.35)'; ctx.fill();
    ctx.strokeStyle = 'rgba(160,135,70,0.5)'; ctx.lineWidth = 0.6; ctx.stroke();
    ctx.restore();
  });
  ctx.restore();
}

function fotoTextura(b64, texto) {
  return new Promise(resolve => {
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas'); c.width=W; c.height=H;
      const ctx = c.getContext('2d');
      fondoGrano(ctx);
      const fX=50, fY=40, fW=W-100, fH=H*0.72;
      ctx.shadowColor='rgba(0,0,0,0.15)'; ctx.shadowBlur=12; ctx.shadowOffsetY=4;
      ctx.fillStyle='#fff'; ctx.fillRect(fX-3, fY-3, fW+6, fH+6);
      ctx.shadowColor='transparent'; ctx.shadowBlur=0; ctx.shadowOffsetY=0;
      ctx.save(); ctx.beginPath(); ctx.rect(fX,fY,fW,fH); ctx.clip();
      const ir=img.width/img.height, br=fW/fH;
      let dW,dH,dX,dY;
      if (ir>br) { dH=fH; dW=fH*ir; dX=fX-(dW-fW)/2; dY=fY; }
      else { dW=fW; dH=fW/ir; dX=fX; dY=fY-(dH-fH)/2; }
      ctx.drawImage(img,dX,dY,dW,dH); ctx.restore();
      ctx.strokeStyle='rgba(200,190,175,0.5)'; ctx.lineWidth=1; ctx.strokeRect(fX,fY,fW,fH);
      document.fonts.ready.then(() => {
        ctx.font='italic 300 34px "Cormorant Garamond"';
        ctx.fillStyle='rgba(45,38,28,0.88)';
        ctx.textAlign='center'; ctx.textBaseline='middle';
        const maxW = fW - 20;
        const words = texto.split(' ');
        const lines = [];
        let line = '';
        for (const word of words) {
          const test = line ? line + ' ' + word : word;
          if (ctx.measureText(test).width > maxW && line) {
            lines.push(line);
            line = word;
          } else {
            line = test;
          }
        }
        if (line) lines.push(line);
        const areaY = fY + fH;
        const areaH = H - areaY;
        const lineH = 40;
        const totalH = lines.length * lineH;
        const startY = areaY + (areaH - totalH) / 2 + lineH / 2;
        lines.forEach((l, i) => ctx.fillText(l, W/2, startY + i * lineH));
        resolve(new THREE.CanvasTexture(c));
      });
    };
    img.src = b64;
  });
}

// ── Carta 8 ─────────────────────────────────────────────────
function texCarta8() {
  const c = document.createElement('canvas'); c.width=W; c.height=H;
  const ctx = c.getContext('2d');
  fondoGrano(ctx); rama(ctx);
  document.fonts.ready.then(() => {
    ctx.font='italic 300 48px "Cormorant Garamond"'; ctx.fillStyle='rgba(45,38,28,0.88)';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('todo comienza aquí.', W/2, H/2);
  });
  return new THREE.CanvasTexture(c);
}

// ── Carta 5 ─────────────────────────────────────────────────
function texCarta5() {
  const c = document.createElement('canvas'); c.width=W; c.height=H;
  const ctx = c.getContext('2d');
  fondoGrano(ctx); marcoDorado(ctx);
  document.fonts.ready.then(() => {
    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillStyle='rgba(45,38,28,0.88)';
    [['Y mientras tú crecías...',H/2-70],['yo tenía la suerte',H/2+10],['de verlo de cerca.',H/2+90]].forEach(([t,y]) => {
      ctx.font='italic 300 48px "Cormorant Garamond"'; ctx.fillText(t, W/2, y);
    });
  });
  return new THREE.CanvasTexture(c);
}

// ── Carta 4 ─────────────────────────────────────────────────
function texCarta4() {
  const c = document.createElement('canvas'); c.width=W; c.height=H;
  const ctx = c.getContext('2d');
  fondoGrano(ctx); marcoDorado(ctx);
  document.fonts.ready.then(() => {
    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillStyle='rgba(45,38,28,0.88)';
    [['Estoy orgulloso de la persona',H/2-110],['en la que te estás convirtiendo.',H/2-25],
     ['No solo por lo que logras...',H/2+70],['sino por quién eres.',H/2+155]].forEach(([t,y]) => {
      ctx.font='italic 300 44px "Cormorant Garamond"'; ctx.fillText(t, W/2, y);
    });
  });
  return new THREE.CanvasTexture(c);
}

// ── Carta 3 ─────────────────────────────────────────────────
function texCarta3() {
  const c = document.createElement('canvas'); c.width=W; c.height=H;
  const ctx = c.getContext('2d');
  fondoGrano(ctx, true);
  const conf=['#E8A090','#F0C080','#A8C8E0','#C8A8D8','#A8D8A8','#F0A0B0','#E0C870','#90C0E0'];
  for (let i=0;i<80;i++) {
    const x=Math.random()*W, y=Math.random()*H, col=conf[Math.floor(Math.random()*conf.length)];
    const sz=Math.random()*14+6, r=Math.random()*Math.PI*2;
    ctx.save(); ctx.translate(x,y); ctx.rotate(r); ctx.globalAlpha=Math.random()*0.5+0.25; ctx.fillStyle=col;
    Math.random()>0.5 ? ctx.fillRect(-sz/2,-sz/4,sz,sz/2) : (ctx.beginPath(),ctx.ellipse(0,0,sz/2,sz/3,0,0,Math.PI*2),ctx.fill());
    ctx.globalAlpha=1; ctx.restore();
  }
  function globo(cx,cy,col,sc=1) {
    ctx.save(); ctx.translate(cx,cy); ctx.scale(sc,sc);
    ctx.beginPath(); ctx.ellipse(0,0,38,48,0,0,Math.PI*2); ctx.fillStyle=col; ctx.globalAlpha=0.75; ctx.fill(); ctx.globalAlpha=1;
    ctx.beginPath(); ctx.ellipse(-10,-14,10,14,-0.5,0,Math.PI*2); ctx.fillStyle='rgba(255,255,255,0.35)'; ctx.fill();
    ctx.beginPath(); ctx.moveTo(0,54); ctx.bezierCurveTo(-10,80,10,100,0,130);
    ctx.strokeStyle='rgba(0,0,0,0.2)'; ctx.lineWidth=1; ctx.globalAlpha=0.5; ctx.stroke(); ctx.globalAlpha=1; ctx.restore();
  }
  globo(80,200,'#E8956D',1.1); globo(160,120,'#F0C060',0.85);
  globo(W-80,200,'#C4A0D0',1.0); globo(W-170,130,'#90B8D8',0.9);
  globo(W/2-60,H-80,'#E89098',0.8); globo(W/2+80,H-60,'#A8D8A0',0.75);
  document.fonts.ready.then(() => {
    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillStyle='rgba(80,55,30,0.88)';
    [['Que este año te encuentre feliz.',H/2-70],['Que rías más de lo que dudas.',H/2+10],
     ['Que disfrutes cada momento.',H/2+90]].forEach(([t,y]) => {
      ctx.font='italic 300 46px "Cormorant Garamond"'; ctx.fillText(t, W/2, y);
    });
  });
  return new THREE.CanvasTexture(c);
}

// ── Carta 2 ─────────────────────────────────────────────────
function texCarta2() {
  const c = document.createElement('canvas'); c.width=W; c.height=H;
  const ctx = c.getContext('2d');
  fondoGrano(ctx);
  const numX=W/2, numY=H/2-80;
  ctx.font=`bold 220px Georgia, "Times New Roman", serif`;
  ctx.textAlign='center'; ctx.textBaseline='middle';
  for (let i=10;i>0;i--) { const p=i/10; ctx.fillStyle=`rgba(100,65,5,${0.06+p*0.04})`; ctx.fillText('22',numX+i*1.2,numY+i*1.5); }
  const gb=ctx.createLinearGradient(numX,numY-110,numX,numY+110);
  gb.addColorStop(0,'#FFF0A0'); gb.addColorStop(0.15,'#E8C030'); gb.addColorStop(0.35,'#C89010');
  gb.addColorStop(0.55,'#D4A820'); gb.addColorStop(0.75,'#B07808'); gb.addColorStop(1,'#8B6005');
  ctx.fillStyle=gb; ctx.fillText('22',numX,numY);
  const gsh=ctx.createLinearGradient(numX-120,numY-110,numX+120,numY-20);
  gsh.addColorStop(0,'rgba(255,255,210,0.5)'); gsh.addColorStop(0.5,'rgba(255,245,160,0.2)'); gsh.addColorStop(1,'rgba(255,240,120,0)');
  ctx.fillStyle=gsh; ctx.fillText('22',numX,numY);
  document.fonts.ready.then(() => {
    ctx.strokeStyle='rgba(180,140,40,0.4)'; ctx.lineWidth=1;
    ctx.beginPath(); ctx.moveTo(W/2-140,H/2+100); ctx.lineTo(W/2+140,H/2+100); ctx.stroke();
    ctx.font='300 28px "Cormorant Garamond"'; ctx.fillStyle='rgba(80,60,30,0.65)';
    ctx.textAlign='center'; ctx.fillText('22 vueltas al sol.', W/2, H/2+70);
    ctx.font='italic 300 34px "Cormorant Garamond"'; ctx.fillStyle='rgba(60,45,25,0.82)';
    ctx.fillText('Y algunas de mis favoritas han sido contigo.', W/2, H/2+155);
  });
  return new THREE.CanvasTexture(c);
}

// ── Carta 1 ─────────────────────────────────────────────────
function texCarta1() {
  const c = document.createElement('canvas'); c.width=W; c.height=H;
  const ctx = c.getContext('2d');
  fondoGrano(ctx);
  document.fonts.ready.then(() => {
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.font='300 36px "Cormorant Garamond"'; ctx.fillStyle='rgba(55,45,30,0.75)';
    ctx.fillText('Gracias por dejarme estar en tu historia.', W/2, H/2-140);
    ctx.font='400 115px "Allura"'; ctx.fillStyle='rgba(40,32,20,0.90)';
    ctx.fillText('Feliz 22',W/2, H/2+10);
    const tm=ctx.measureText('Feliz 22.'), tW=tm.width, lY=H/2+68, lX1=W/2-tW/2, lX2=lX1+tW*0.55;
    for (let i=0;i<30;i++) {
      const p=i/30, x=lX1+(lX2-lX1)*(i/30), xx=lX1+(lX2-lX1)*((i+1)/30);
      const g=3.5*(1-p)+0.3*p, al=0.55*(1-p*0.3);
      ctx.strokeStyle=`rgba(40,32,20,${al})`; ctx.lineWidth=g; ctx.lineCap='round';
      ctx.beginPath(); ctx.moveTo(x,lY+Math.sin(p*0.5)*3); ctx.lineTo(xx,lY+Math.sin((p+0.03)*0.5)*3); ctx.stroke();
    }
    ctx.font='italic 300 40px "Cormorant Garamond"'; ctx.fillStyle='rgba(55,45,30,0.72)';
    ctx.textAlign='right'; ctx.fillText('— Omar', W-80, H-90);
  });
  return new THREE.CanvasTexture(c);
}


const FOTO7_B64 = 'data:image/png;base64,';
const FOTO6_B64 = 'data:image/png;base64,';


export async function cargarTexturas() {
  await document.fonts.ready;
  const [tex7, tex6] = await Promise.all([
    fotoTextura(FOTO7_B64, 'No sabía que ese día empezaba algo que duraría años.'),
    fotoTextura(FOTO6_B64, 'Han pasado los años. Muchas cosas cambiaron. Pero seguimos creando recuerdos.'),
  ]);
  return {
    carta1: texCarta1(),
    carta2: texCarta2(),
    carta3: texCarta3(),
    carta4: texCarta4(),
    carta5: texCarta5(),
    carta6: tex6,
    carta7: tex7,
    carta8: texCarta8(),
  };
}